/** Seed 14 régions Wolof — sauts de ligne réels. */
$json = <<<'JSON'
{"region-de-dakar":{"title_wo":"Diiwaanu Dakar","excerpt_wo":"Diiwaan bu gën a ndaw ci superficie, waaye Dakar mooy dëkk bu mag bu politik, ekonom ak administrasyon.","content_wo":"### Jëmmal\n\nDiiwaanu Dakar mooy diiwaan bu gën a ndaw ci Senegaal ci kaw superficie, waaye mu am solo lool ci mbirum politik, ekonom, administrasyon ak way-dëkk. Dakar, dëkk bu mag bu réew mi, nekk na ci péninsule Cap-Vert, ci wetug géej gi.\n\n### Géeographie\n\nDakar dafa aju ci Atlantique ci norte, sowwu ak sud ; Thiès mooy ci penku. Péninsule Cap-Vert, Îles de la Madeleine ak Gorée bokk nañu ci paysage bi.\n\n### Taariix\n\nTaariixu Dakar dafa lëkkale ak Cap-Vert ak Gorée. Gannaaw indipendance ci 1960, Dakar des na capitale bu République du Senegaal.\n\n### Toppatoo\n\nJuróom-benn départements : Dakar, Guédiawaye, Pikine, Keur Massar ak Rufisque.\n\n### Ekonom ak aada\n\nCommerce, services, banques, numérique ak tourisme. Gorée, Monument de la Renaissance Africaine, Corniche, Village des Arts ak marchés yu mag yi."},"region-de-ziguinchor":{"title_wo":"Diiwaanu Ziguinchor","excerpt_wo":"Xolum Casamance — mangrove, tourisme, aada yu Diola ak askan yu wuute.","content_wo":"### Jëmmal\n\nDiiwaanu Ziguinchor nekk na ci penku-sowwu Senegaal. Mooy xolum Casamance ci mbirum taariix, ekonom ak aada.\n\n### Géeographie\n\nGambia ci norte, Sédhiou ci penku, Guinée-Bissau ci sud, Atlantique ci sowwu. Ziguinchor mooy chef-lieu.\n\n### Aada\n\nCasamance dafa fees ak aada yu wuute — Diola, Mandingue, Balante, Peul ak Wolof. Fecc, musik ak architecture traditionnelle am nañu solo.\n\n### Toppatoo\n\nÑetti départements : Ziguinchor, Oussouye ak Bignona.\n\n### Tourisme\n\nCap Skirring, mangrove yi, duni yi ak plages yu Casamance."},"region-de-thies":{"title_wo":"Diiwaanu Thiès","excerpt_wo":"Bunt bu jëm ci littoral — industrie, Lac Rose, Petite Côte ak Bandia.","content_wo":"### Jëmmal\n\nDiiwaanu Thiès nekk na ci penku Dakar. Mooy benn ci diiwaan yu am solo ci industrie, transport, agriculture ak tourisme.\n\n### Toppatoo\n\nDépartements : Thiès, Tivaouane ak Mbour.\n\n### Nature ak tourisme\n\nLac Rose (Lac Retba), Petite Côte (Saly, Somone, Popenguine), forêt de Bandia ak bérab yu aada yi.\n\n### Ekonom\n\nIndustrie, commerce, agriculture ak tourisme littoral."},"region-de-saint-louis":{"title_wo":"Diiwaanu Ndar (Saint-Louis)","excerpt_wo":"Dëkk bu UNESCO, dexu Senegaal, Langue de Barbarie ak taariix bu yàgg.","content_wo":"### Jëmmal\n\nNdar (Saint-Louis) mooy dëkk bu taariix, patrimoine mondial UNESCO. Diiwaan bi nekk na ci norte Senegaal, ci wetug dexu Senegaal.\n\n### Taariix\n\nNdar doon na capitale bu Afrique occidentale française. Île de Saint-Louis, Pont Faidherbe ak architecture coloniale xam nañu leen ci àdduna bi.\n\n### Nature\n\nLangue de Barbarie, Parc national, dex gi ak géej gi.\n\n### Ekonom\n\nPêche, agriculture, tourisme culturel ak naturel."},"region-de-diourbel":{"title_wo":"Diiwaanu Diourbel","excerpt_wo":"Baol — Touba, aada Mouride, agriculture ak terroirs.","content_wo":"### Jëmmal\n\nDiiwaanu Diourbel nekk na ci xolum Baol. Xam nañu ko ci Touba, centre spirituel Mouride, ak agriculture.\n\n### Aada ak diine\n\nTouba ak Grand Magal am nañu solo lool ci aada, diine ak ekonomu centre Senegaal. Mausolée bu Cheikh Ahmadou Bamba mooy bérab bu ñu gën a séen.\n\n### Toppatoo\n\nDépartements : Diourbel, Bambey ak Mbacké.\n\n### Ekonom\n\nAgriculture (arachide, mil), commerce ak tourisme religieux."},"region-de-kaolack":{"title_wo":"Diiwaanu Kaolack","excerpt_wo":"Carrefour bu bassin arachidier — Saalum, commerce, sel ak transport.","content_wo":"### Jëmmal\n\nKaolack mooy carrefour economique ci centre Senegaal, rawatina ci commerce arachide ak dexu Saalum.\n\n### Toppatoo\n\nDépartements : Kaolack, Guinguinéo ak Nioro du Rip.\n\n### Ekonom\n\nAgriculture, commerce, sel bu Kaolack ak transport. Marchés yu mag yi am nañu solo ci réew mi."},"region-de-kaffrine":{"title_wo":"Diiwaanu Kaffrine","excerpt_wo":"Xolum agro-pastoral bu centre (sosu na ci 2008) — arachide, mil ak sàmm.","content_wo":"### Jëmmal\n\nDiiwaanu Kaffrine sosu na ci 2008. Mooy territoire agro-pastoral ci centre Senegaal, diggante Kaolack ak Tambacounda.\n\n### Toppatoo\n\nDépartements : Kaffrine, Birkelane, Koungheul ak Malem Hodar.\n\n### Ekonom\n\nAgriculture, sàmm ak commerce yu local. Arachide, mil ak niébé bokk nañu ci tool yi."},"region-de-fatick":{"title_wo":"Diiwaanu Fatick","excerpt_wo":"Siin-Saalum — delta, mangrove, aada Sereer ak réserve UNESCO.","content_wo":"### Jëmmal\n\nFatick xam nañu ko ci Delta du Saloum, patrimoine naturel ak culture Sereer.\n\n### Nature\n\nÎles du Saloum, mangrove, bolong yi ak réserve de biosphère UNESCO. Joal-Fadiouth, Palmarin ak Foundiougne.\n\n### Toppatoo\n\nDépartements : Fatick, Foundiougne ak Gossas.\n\n### Aada\n\nAada Sereer, saltigues, ndut ak tourisme écologique."},"region-de-louga":{"title_wo":"Diiwaanu Louga","excerpt_wo":"Bunt yu Sahel — Ndiambour, sàmm, agriculture ak Ferlo.","content_wo":"### Jëmmal\n\nLouga nekk na ci norte Senegaal, diggante Saint-Louis ak Matam. Territoire pastoral ak agricole, xam ko ci Ndiambour.\n\n### Toppatoo\n\nDépartements : Louga, Kébémer ak Linguère.\n\n### Ekonom\n\nSàmm, agriculture (arachide, niébé) ak commerce. Ferlo jege na ci penku."},"region-de-matam":{"title_wo":"Diiwaanu Matam","excerpt_wo":"Wàllu dexu Senegaal — Fouta-Toro, agriculture, sàmm ak aada Peul.","content_wo":"### Jëmmal\n\nMatam nekk na ci nord-est, ci wetug dexu Senegaal. Zone agricole ak pastorale, xolum Fouta-Toro.\n\n### Toppatoo\n\nDépartements : Matam, Kanel ak Ranérou-Ferlo.\n\n### Ekonom ak aada\n\nAgriculture bu wàllu dex gi, sàmm, commerce ak Mauritanie. Aada Peul ak Haalpulaar am na solo."},"region-de-tambacounda":{"title_wo":"Diiwaanu Tambacounda","excerpt_wo":"Diiwaan bu gën a rëy — Niokolo-Koba, penku ak nature.","content_wo":"### Jëmmal\n\nTambacounda mooy diiwaan bu gën a rëy ci Senegaal. Niokolo-Koba bokk na ci patrimoine naturel bu àdduna bi.\n\n### Nature\n\nParc national du Niokolo-Koba (UNESCO), àll yi ak rab yu àll — lion, éléphant, hippopotame.\n\n### Toppatoo\n\nDépartements : Tambacounda, Bakel, Goudiry ak Koumpentoum.\n\n### Ekonom\n\nAgriculture, sàmm, or ak tourisme nature."},"region-de-kedougou":{"title_wo":"Diiwaanu Kédougou","excerpt_wo":"Sud-est — chutes de Dindéfélo, pays Bassari, or ak nature.","content_wo":"### Jëmmal\n\nKédougou nekk na ci sud-est Senegaal. Xam nañu ko ci nature, or ak aada Bassari, Peul ak Bédik.\n\n### Nature ak aada\n\nChutes de Dindéfélo, pays Bassari (UNESCO), montagne yi ak askan yu wuute. Paysages culturels Bassari, Peul et Bédik.\n\n### Toppatoo\n\nDépartements : Kédougou, Saraya ak Salémata.\n\n### Ekonom\n\nOr, agriculture, tourisme nature ak culturel."},"region-de-kolda":{"title_wo":"Diiwaanu Kolda","excerpt_wo":"Fouladou — Haute Casamance, agriculture, sàmm ak aada yu wuute.","content_wo":"### Jëmmal\n\nKolda nekk na ci Haute Casamance, territoire Fouladou. Zone bu fees ak agriculture ak sàmm.\n\n### Toppatoo\n\nDépartements : Kolda, Vélingara ak Médina Yoro Foulah.\n\n### Ekonom ak aada\n\nAgriculture (riz, arachide), sàmm ak commerce. Aada Peul, Mandingue ak askan yu Haute Casamance."},"region-de-sedhiou":{"title_wo":"Diiwaanu Sédhiou","excerpt_wo":"Casamance — vallées, àll yi, aada yu wuute ak patrimoine.","content_wo":"### Jëmmal\n\nSédhiou nekk na ci Casamance, diggante Ziguinchor ak Kolda. Vallées, àll yi ak dëkk yu aada.\n\n### Toppatoo\n\nDépartements : Sédhiou, Bounkiling ak Goudomp.\n\n### Ekonom\n\nAgriculture, pêche ci dex yi ak commerce local. Riz bu Casamance am na solo ci dundin."}}
JSON;
